<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
interface Wedding { id: number; name: string; authorized_capacity: number | null }
interface SeatRequest { id: number; requested_count: number; approved_count: number | null; status: string; request_note: string | null; decision_reason: string | null }
interface Family { id: number; label: string; responsible_name: string | null; current_allocation: number; original_allocation: number; rsvp_status: string; attending_count: number | null; members_count: number; additional_seat_requests: SeatRequest[] }
const props = defineProps<{ wedding: Wedding; families: Family[]; assignedSeats: number; availableSeats: number | null; canEdit: boolean }>();
const form = useForm({ label: '', responsible_name: '', responsible_email: '', responsible_phone: '', allocation: 1 });
function submit(): void { form.post(route('weddings.families.store', props.wedding.id), { preserveScroll: true, onSuccess: () => form.reset() }); }
function resolveRequest(id: number, decision: 'approved' | 'rejected', approvedCount?: number): void { router.patch(route('weddings.additional-seats.resolve', [props.wedding.id, id]), { decision, approved_count: approvedCount, decision_reason: decision === 'rejected' ? 'Sin disponibilidad actualmente.' : null }, { preserveScroll: true }); }
</script>
<template><Head :title="`Familias · ${wedding.name}`"/><AuthenticatedLayout><template #header><div><Link :href="route('weddings.show', wedding.id)" class="text-sm text-rose-800 underline underline-offset-4">← Expediente</Link><h1 class="mt-1 font-serif text-3xl text-stone-800">Familias y pases</h1></div></template><div class="mx-auto max-w-6xl px-4 py-8 sm:px-6"><div class="grid gap-4 sm:grid-cols-3"><div class="rounded-xl bg-stone-800 p-4 text-white"><p class="text-sm text-rose-100">Asignados vigentes</p><p class="mt-1 text-2xl font-semibold">{{ assignedSeats }}</p></div><div class="rounded-xl border border-stone-200 bg-white p-4"><p class="text-sm text-stone-500">Disponibles</p><p class="mt-1 text-2xl font-semibold text-stone-800">{{ availableSeats ?? 'Pendiente' }}</p></div><div class="rounded-xl border border-stone-200 bg-white p-4"><p class="text-sm text-stone-500">Confirmados</p><p class="mt-1 text-2xl font-semibold text-stone-800">{{ families.reduce((total, family) => total + (family.attending_count ?? 0), 0) }}</p></div></div><div class="mt-6 grid gap-6 lg:grid-cols-3"><section class="lg:col-span-2 overflow-hidden rounded-2xl border border-stone-200 bg-white"><table class="min-w-full text-left text-sm"><thead class="bg-stone-50 text-stone-500"><tr><th class="p-4">Familia</th><th class="p-4">Pases vigentes</th><th class="p-4">Respuesta</th></tr></thead><tbody><tr v-for="family in families" :key="family.id" class="border-t border-stone-100"><td class="p-4"><p class="font-medium text-stone-800">{{ family.label }}</p><p class="text-stone-500">{{ family.responsible_name || 'Responsable pendiente' }}</p><div v-for="item in family.additional_seat_requests" :key="item.id" class="mt-2 rounded-lg bg-rose-50 p-2 text-xs text-rose-950"><p>Solicitud de {{ item.requested_count }} lugar(es): {{ item.status }}<span v-if="item.approved_count !== null"> · aprobados {{ item.approved_count }}</span></p><p v-if="item.request_note" class="mt-1">{{ item.request_note }}</p><p v-if="item.decision_reason" class="mt-1">{{ item.decision_reason }}</p><div v-if="canEdit && item.status === 'pending'" class="mt-2 flex gap-2"><button class="rounded border border-rose-700 px-2 py-1 text-rose-800" @click="resolveRequest(item.id, 'approved', item.requested_count)">Aprobar {{ item.requested_count }}</button><button class="rounded border border-stone-400 px-2 py-1 text-stone-700" @click="resolveRequest(item.id, 'rejected')">Rechazar</button></div></div></td><td class="p-4">{{ family.current_allocation }} <span v-if="family.current_allocation !== family.original_allocation" class="text-stone-500">(original: {{ family.original_allocation }})</span></td><td class="p-4">{{ family.rsvp_status }}<span v-if="family.attending_count !== null"> · {{ family.attending_count }}</span></td></tr><tr v-if="!families.length"><td colspan="3" class="p-6 text-center text-stone-500">No hay familias registradas.</td></tr></tbody></table></section><form v-if="canEdit" class="rounded-2xl border border-stone-200 bg-white p-5" @submit.prevent="submit"><h2 class="font-serif text-xl text-stone-800">Nueva familia</h2><div class="mt-4 space-y-3"><input v-model="form.label" placeholder="Nombre identificador" required class="w-full rounded-lg border-stone-300"><input v-model="form.responsible_name" placeholder="Responsable" class="w-full rounded-lg border-stone-300"><input v-model="form.responsible_email" type="email" placeholder="Correo" class="w-full rounded-lg border-stone-300"><input v-model="form.responsible_phone" type="tel" placeholder="Teléfono / WhatsApp" class="w-full rounded-lg border-stone-300"><input v-model.number="form.allocation" type="number" min="1" placeholder="Pases" required class="w-full rounded-lg border-stone-300"><p v-if="form.errors.allocation" class="text-sm text-red-700">{{ form.errors.allocation }}</p><button class="rounded-lg bg-rose-800 px-4 py-2 text-sm font-medium text-white">Crear familia</button></div></form></div></div></AuthenticatedLayout></template>
